[2022년 30번] 다음은 검색 알고리즘에 관한 JAVA Code 문제이다. 숫자 배열 {1, 2, 3, 4}와 정수 k는 3으로 입력되었을 때, 출력 결과로 가장 적절한 것은?

public class Search {
  public static int search(List<Integer> list, int k) {
    int left = 0, right = list.size() - 1, result = -1;
    while(left <= right) {
      int mid = left + ((right - left) / 2);
      if (list.get(mid) > k) {
        right = mid -1;
      } else if (list.get(mid) == k) {
        result = mid;
        right = mid -1;
      } else {
        left = mid+1;
      }
    }
    return result;
  }
  public static void main(String[] args) {
    Integer[] intArr = {1, 2, 3, 4};
    List<Integer> list = Arrays.asList(intArr);
    System.out.println(search(list, 3));
  }
}

